<script lang="ts">
 import {api} from './api';import {untrack} from 'svelte';
 let {company,onupdated}:{company:string;onupdated:()=>void}=$props();
 let data:any=$state(null),form:any=$state(null),holidays=$state(''),busy=$state(false),error=$state(''),notice=$state('');
 const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
 async function load(){try{data=await api('/sample-capacities')}catch(e){error=(e as Error).message}}
 $effect(()=>{company;untrack(load)});
 function edit(record:any=null){error='';notice='';form=record?structuredClone($state.snapshot(record)):{company_id:Number(company),resource:'General',effective_date:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}),tailors:1,pieces_per_tailor:2,weekly_off:[0]};holidays=(record?.holidays||[]).join('\n')}
 async function save(){if(busy)return;busy=true;error='';try{await api('/sample-capacities',{...form,holidays:holidays.split(/[\n,]/).map(s=>s.trim()).filter(Boolean)});form=null;await load();onupdated();notice='Capacity saved. Future plan previews use the dated capacity; frozen plans keep their agreed dates.'}catch(e){error=(e as Error).message}finally{busy=false}}
</script>
<section><header><div><h3>Sampling capacity</h3><p>General, Suits and additional production lines. Capacity = tailors × pieces per tailor per day. For a line allowance, enter 1 resource and its daily allowance.</p></div>{#if data?.can_edit}<button class="button primary" disabled={!company} onclick={()=>edit()}>Add dated capacity</button>{/if}</header>
{#if !company}<p>Select a workspace company to configure capacity.</p>{/if}{#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
<div class="scroll"><table><thead><tr><th>Resource</th><th>Effective from</th><th>Tailors / resources</th><th>Pieces each</th><th>Daily capacity</th><th>Weekly off</th><th>Holidays</th><th></th></tr></thead><tbody>{#each (data?.records||[]).filter((r:any)=>String(r.company_id)===company) as r}<tr><td>{r.resource}</td><td>{r.effective_date}</td><td>{r.tailors}</td><td>{r.pieces_per_tailor}</td><td><strong>{r.tailors*r.pieces_per_tailor}</strong></td><td>{r.weekly_off.map((n:number)=>days[n]).join(', ')||'None'}</td><td>{r.holidays.join(', ')||'None'}</td><td>{#if data.can_edit}<button class="text-button" onclick={()=>edit(r)}>Edit</button>{/if}</td></tr>{:else}<tr><td colspan="8">Super Admin must enter the real capacity before a plan can be frozen.</td></tr>{/each}</tbody></table></div>
{#if form}<div class="editor"><h3>{form.id?'Edit':'Add'} capacity</h3><div class="grid"><label>Resource<input list="sample-resource-names" bind:value={form.resource} readonly={!!form.id}/><datalist id="sample-resource-names"><option>General</option><option>Suits</option><option>Line 1</option><option>Line 2</option></datalist></label><label>Effective date<input type="date" bind:value={form.effective_date} readonly={!!form.id}/></label><label>Tailors / resources (0 pauses capacity)<input type="number" min="0" max="500" step="1" bind:value={form.tailors}/></label><label>Pieces per tailor per day<input type="number" min="1" max="200" step="1" bind:value={form.pieces_per_tailor}/></label><fieldset><legend>Weekly off</legend>{#each days as day,n}<label class="check"><input type="checkbox" checked={form.weekly_off.includes(n)} onchange={e=>form.weekly_off=e.currentTarget.checked?[...form.weekly_off,n]:form.weekly_off.filter((v:number)=>v!==n)}/>{day}</label>{/each}</fieldset><label>Holidays (YYYY-MM-DD, one per line)<textarea rows="6" bind:value={holidays}></textarea></label></div><p>Add a new effective-date entry for a joining or leaving change. It takes effect from that date until the next entry for the resource.</p><footer><button class="button primary" disabled={busy} onclick={save}>Save capacity</button><button class="button secondary" disabled={busy} onclick={()=>form=null}>Cancel</button></footer></div>{/if}
</section>
<style>header{display:flex;justify-content:space-between;align-items:start;gap:20px;margin:20px 0}header p{max-width:720px;line-height:1.5}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #c4d3dc}.editor{background:#edf4f7;border:1px solid #b4c8d1;border-radius:12px;padding:20px;margin:20px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}label{display:grid;gap:7px;font-weight:700;color:#122533}input,textarea{width:100%;background:#eff5fa;padding:10px;border:1px solid #adc1cc;border-radius:7px;color:#101820;font:inherit}.check{display:flex;align-items:center;margin:7px 0}.check input{width:18px;height:18px}fieldset{border:1px solid #adc1cc;border-radius:8px}footer{display:flex;gap:10px;margin-top:18px}@media(max-width:700px){header{flex-direction:column}.grid{grid-template-columns:1fr}}</style>
